window.TRIASSIC_DECIDED = {"cymbospondylus":{"verdict":"replace","choice":"web","ref":"Cymbospondylus youngorum reconstruction 2023.jpg","note":"","at":"2026-09-13T01:00:13.500Z"},"shonisaurus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:00:47.144Z"},"nothosaurus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:01:08.730Z"},"dinocephalosaurus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:01:15.101Z"},"helicoprion":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:01:22.623Z"},"rhaeticosaurus":{"verdict":"replace","choice":"canonical","ref":"canonical","note":"Redraw only — the reading of the animal is accepted. The rear fins are wrong: an extra fin rises off the back above the tail, and a plesiosaur has no dorsal fin. Rhaeticosaurus is a four-flipper underwater flier, so the hind pair must be flippers seated low on the flanks at the pelvis, mirroring the fore pair in shape and size, with the tail short and unfinned between them. Keep the pose, the colouring, the mottling, the sunlit shallow-reef setting and the underwater three-quarter camera exactly as they are.","at":"2026-09-13T02:30:00.000Z"},"atopodentatus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:02:09.321Z"},"askeptosaurus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:02:52.596Z"},"placodus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:03:01.825Z"},"hybodus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:03:09.333Z"},"birgeria":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:03:25.643Z"},"aphaneramma":{"verdict":"replace","choice":"web","ref":"Metoposaurus diagnosticus kraselovi 1DB.jpg","note":"","at":"2026-09-13T01:04:06.153Z"},"mixosaurus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:04:33.564Z"},"henodus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:04:55.343Z"},"saurichthys":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:05:07.724Z"},"hupehsuchus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:05:32.675Z"},"cartorhynchus":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:06:03.044Z"},"odontochelys":{"verdict":"replace","choice":"web","ref":"Thaichelys ruchae life restoration.png","note":"","at":"2026-09-13T01:06:24.789Z"},"ceratites":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:06:29.964Z"},"phragmoteuthis":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:06:43.197Z"},"tanystropheus":{"verdict":"replace","choice":"canonical","ref":"canonical","note":"Redraw for scale — the anatomy is right but everything around it says lizard. This animal is 5.5-6 m with a neck of about 3 m on a trunk of about 1.5 m, and the current frame (ankle-deep water, pebbles, small weed, a distant headland, a high wide camera) reads it at well under a metre. Put the camera low and close, at or just above the waterline and near enough that the trunk fills the frame with the neck running out of it; stand it in water at elbow depth against boulders rather than pebbles; and pose it as the slot actually is, the neck swung out low over the water from the bank, ready to strike at something in it. Keep the species, the proportions, the banded mottling and the clear shallow-marine setting.","at":"2026-09-13T02:30:01.000Z"},"mystriosuchus":{"verdict":"replace","choice":"canonical","ref":"canonical","note":"Redraw into the water — the current pose is a high walk across a mudflat, and this animal is never seen out of the water in play. Draw it swimming: body wholly in the water, limbs folded back against the flanks, the tail sculling, and the dorsal crest, the eyes and the tip of the snout breaking the surface as the design requires of the model. A low camera close to the waterline, part of the body read through the water. Keep the species, the crocodile-like proportions, the long narrow snout and the armour. Two fixes to the setting: the mangrove roots and pneumatophores in the foreground are tens of millions of years too early, so replace them with Triassic lagoon margin — horsetails, Voltzia conifers, drift logs; and the light and the water should read marine lagoon rather than estuarine mud.","at":"2026-09-13T02:30:02.000Z"},"coelophysis":{"verdict":"greenlit","choice":"canonical","ref":"canonical","note":"","at":"2026-09-13T01:07:28.068Z"},"keichousaurus":{"verdict":"greenlit","choice":"canonical","ref":"male","note":"","at":"2026-09-13T01:05:52.838Z"}};
